/* 3D orb: tilt with the pointer */
document.addEventListener('DOMContentLoaded', () => {
  const card = document.querySelector('.orb-card');
  const stage = document.querySelector('.orb-stage');
  if (!card || !stage || (window.matchMedia && matchMedia('(prefers-reduced-motion: reduce)').matches)) return;
  let raf = 0;
  const set = (rx, ry) => { cancelAnimationFrame(raf); raf = requestAnimationFrame(() => { stage.style.setProperty('--rx', rx + 'deg'); stage.style.setProperty('--ry', ry + 'deg'); }); };
  card.addEventListener('pointermove', (e) => {
    const r = card.getBoundingClientRect();
    const x = (e.clientX - r.left) / r.width - 0.5;
    const y = (e.clientY - r.top) / r.height - 0.5;
    set(-10 - y * 24, x * 30);
  });
  card.addEventListener('pointerleave', () => set(-10, 0));
});
